c(46, "§0.1; §5.2 (competitor cap); §3.7", "anti-pattern", "The competitor pattern this app's users fled, in their own words: 'most of them only let you make around 4 habits before tealling you to pay'; 'a monthly sub for an app like habitkit, which offers no benefit over this app'; 'the alternatives have paid subscriptions' — so a developer nearly wrote their own tracker; 'almost all of them need some sort of payment'; 'too many features for my liking' — a small-cap freemium with a monthly subscription and feature bloat is the category default reviewers are escaping.", "category default: ~4-habit cap + monthly subscription", "churn", "paywall_contrast 16 / 18.60%; TRIED_MANY 16", "dont", "High-priority", "generalisable", ["13903380759", "13546859530", "14227392787", "13469159788", "13682234945"], "", "")

